package org.slavicmyths.verify;
import java.util.*;import java.nio.file.*;
import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.commands.arguments.blocks.BlockStateParser;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.*;
import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import org.slavicmyths.yaga.*;
/** Prepared extreme-terrain fixtures in a disposable real server; explicitly not natural-generation evidence. */
@EventBusSubscriber(modid="slavicmyths") public final class Yaga300 {
 static ServerLevel w;static String mode;static long began,pre;static int phase,index,column,voxel=50;static boolean done;static final List<ChunkPos> chunks=new ArrayList<>(),held=new ArrayList<>();static final TicketType<Long> TICKET=TicketType.create("qa300_yaga",Long::compare);static YagaPlacement.Cursor cursor;static YagaPlacement.Site snapshot;static BlockPos candidate=new BlockPos(0,80,0);static final List<Map<String,Object>> checks=new ArrayList<>();static final Map<String,Object> out=new LinkedHashMap<>();static final List<Long> times=new ArrayList<>();
 static void check(boolean ok,String label){checks.add(Map.of("status",ok?"PASS":"FAIL","test",label));System.out.println("QA300_YAGA "+(ok?"PASS ":"FAIL ")+label);}
 @SubscribeEvent public static void start(net.neoforged.neoforge.event.server.ServerStartedEvent e){mode=System.getProperty("slavicmyths.qa300","");if(!mode.startsWith("yaga"))return;w=e.getServer().overworld();began=System.nanoTime();out.put("mode",mode);out.put("seed",w.getSeed());out.put("scope","EXPLICIT_PREPARED_TERRAIN; not natural city or full Survival progression");if(mode.equals("yaga-restart")){candidate=YagaData.get(w).anchor;if(candidate==null){finish(new IllegalStateException("no saved house"));return;}phase=10;}for(int x=(candidate.getX()-18)>>4;x<=(candidate.getX()+18)>>4;x++)for(int z=(candidate.getZ()-26)>>4;z<=(candidate.getZ()+18)>>4;z++)chunks.add(new ChunkPos(x,z));}
 @SubscribeEvent public static void pre(net.neoforged.neoforge.event.tick.ServerTickEvent.Pre e){pre=System.nanoTime();}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(w==null||done)return;times.add(System.nanoTime()-pre);try{
  if(System.nanoTime()-began>300_000_000_000L)throw new IllegalStateException("5min fixture bound phase="+phase);
  if(index<chunks.size()){var p=chunks.get(index);if(!held.contains(p)){w.getChunkSource().addRegionTicket(TICKET,p,0,300L);held.add(p);return;}if(w.getChunkSource().getChunkNow(p.x,p.z)!=null)index++;return;}
  if(phase==10){if(w.getGameTime()%40!=0)return;var d=YagaData.get(w);check(d.placed&&w.getEntity(d.npc) instanceof BabaYaga,"actual saved canonical Yaga loads after new JVM");check(d.kuzya!=null&&w.getEntity(d.kuzya) instanceof org.slavicmyths.kuzya.KuzyaEntity,"actual saved Kuzya loads after new JVM");check(w.getBlockEntity(d.anchor.offset(-4,4,5)) instanceof net.minecraft.world.level.block.entity.BarrelBlockEntity,"household barrel survived actual restart");var repeat=YagaHut.beginPlace(w,d.anchor);check(repeat.done()&&!repeat.result.ok&&repeat.result.reason.equals("exists"),"repeat after restart refuses second house");out.put("anchor",d.anchor.toShortString());out.put("npc",d.npc.toString());out.put("kuzya",d.kuzya.toString());finish(null);return;}
  if(phase==0){int operations=0;while(column<37*45&&operations++<2048){int x=column/45-18,z=column%45-26;int g=mode.equals("yaga-slope")?80+Math.floorDiv(x,4):mode.equals("yaga-cliff")&&x>=0?55:80;var p=new BlockPos(x,voxel,z);w.setBlock(p,voxel>g?Blocks.AIR.defaultBlockState():voxel==g?Blocks.GRASS_BLOCK.defaultBlockState():Blocks.DIRT.defaultBlockState(),2|16);if(++voxel>=w.getMaxBuildHeight()){voxel=50;column++;}}if(column==37*45){if(mode.equals("yaga-forest")){for(int x:new int[]{-6,0,6})for(int z:new int[]{-8,0,7}){for(int y=81;y<=88;y++)w.setBlock(new BlockPos(x,y,z),Blocks.OAK_LOG.defaultBlockState(),2|16);for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++)for(int y=88;y<=90;y++)w.setBlock(new BlockPos(x+dx,y,z+dz),Blocks.OAK_LEAVES.defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.PERSISTENT,true),2|16);}}phase=1;}return;}
  if(phase==1){if(mode.equals("yaga-cliff")){var site=YagaPlacement.prepareForCreation(w,candidate,new YagaHutPlan(),Yaga300::state);check(site.failure!=null,"deep cliff rejected before first write");out.put("cliff_rejection",site.failure==null?"NONE":site.failure.reason);check(!YagaData.get(w).placed,"cliff refusal never sets placed/NPC state");finish(null);return;}
   for(Block b:new Block[]{Blocks.CHEST,Blocks.END_PORTAL_FRAME,Blocks.BEDROCK}){var p=new BlockPos(0,80,0);var old=w.getBlockState(p);w.setBlock(p,b.defaultBlockState(),2|16);var rejected=YagaPlacement.prepareForCreation(w,candidate,new YagaHutPlan(),Yaga300::state);check(rejected.failure!=null&&w.getBlockState(p).is(b),"preflight protects "+b);w.setBlock(p,old,2|16);}
   snapshot=YagaPlacement.prepareForCreation(w,candidate,new YagaHutPlan(),Yaga300::state);if(snapshot.failure!=null)throw new IllegalStateException("fixture not accepted: "+snapshot.failure.reason+" "+snapshot.failure.pos);out.put("anchor",snapshot.anchor.toShortString());out.put("planned_destinations",snapshot.desired.size());cursor=YagaHut.beginPlace(w,candidate);cursor.step(256,2_000_000);cursor.abort();phase=2;return;
  }
  if(phase==2){cursor.step(256,2_000_000);if(!cursor.done())return;check(!cursor.result.ok&&!YagaData.get(w).placed,"cancelled partial house never claims placed");check(snapshot.old.entrySet().stream().allMatch(entry->w.getBlockState(entry.getKey()).equals(entry.getValue())),"rollback restores every snapshotted terrain/house destination");check(org.slavicmyths.worldgen.ManualStructureRecords.get(w).entries().isEmpty(),"cancel releases own construction reservation");cursor=YagaHut.beginPlace(w,candidate);phase=3;return;}
  if(phase==3){cursor.step(256,2_000_000);if(!cursor.done())return;check(cursor.result.ok,"actual bounded house placement succeeds: "+cursor.result.reason);if(!cursor.result.ok)throw new IllegalStateException("placement failed "+cursor.result.reason);var d=YagaData.get(w);check(d.placed&&w.getEntity(d.npc) instanceof BabaYaga,"real canonical Yaga exists only after full house");check(d.kuzya!=null&&w.getEntity(d.kuzya) instanceof org.slavicmyths.kuzya.KuzyaEntity,"real Kuzya exists after full house");check(w.getBlockEntity(d.anchor.offset(-4,4,5)) instanceof net.minecraft.world.level.block.entity.BarrelBlockEntity,"actual household loot barrel exists");int unsupported=0,maxCoarse=0;for(int x=-9;x<=9;x++)for(int z=-16;z<=9;z++){var p=d.anchor.offset(x,-1,z);if(!w.getBlockState(p).isCollisionShapeFullBlock(w,p))unsupported++;int run=0;for(int y=d.anchor.getY();y>=d.anchor.getY()-10;y--){if(w.getBlockState(new BlockPos(x,y,z)).is(Blocks.COARSE_DIRT)){run++;maxCoarse=Math.max(maxCoarse,run);}else run=0;}}check(unsupported==0,"whole yard has solid continuous ground: unsupported="+unsupported);check(maxCoarse<=1,"no coarse_dirt foundation columns: maxRun="+maxCoarse);out.put("max_coarse_dirt_run",maxCoarse);out.put("npc",d.npc.toString());out.put("kuzya",d.kuzya.toString());var repeat=YagaHut.beginPlace(w,candidate);check(repeat.done()&&!repeat.result.ok&&repeat.result.reason.equals("exists"),"second request preserves unique saved house");finish(null);}
 }catch(Throwable x){finish(x);}}
 static BlockState state(String s){try{return BlockStateParser.parseForBlock(BuiltInRegistries.BLOCK.asLookup(),s,false).blockState();}catch(Exception x){throw new RuntimeException(x);}}
 static void finish(Throwable x){done=true;for(var p:held)w.getChunkSource().removeRegionTicket(TICKET,p,0,300L);out.put("checks",checks);out.put("error",x==null?null:x.toString());out.put("status",x==null&&checks.stream().allMatch(c->c.get("status").equals("PASS"))?"PASS_SCOPED_FIXTURE":"FAIL");out.put("elapsed_s",(System.nanoTime()-began)/1e9);Collections.sort(times);out.put("p95_ms",times.isEmpty()?0:times.get((int)(times.size()*.95))/1e6);try{Files.writeString(Path.of("yaga300-"+mode+".json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));}catch(Exception ex){ex.printStackTrace();}if(x!=null)x.printStackTrace();w.getServer().saveEverything(false,true,true);w.getServer().halt(false);}
}
